//! Host for custom tool UIs (`ui = "custom"`): the same plumbing as [`crate::AutoTool`] (mode,
//! language, runner, cancellation, native save) exposed to a tool's own `Ui` component through
//! [`use_tool`]. Wrappers generated by xtask render `ToolHost { tool::ui::Ui {} }`.
use dioxus::prelude::*;
use kortex_contract::ToolContract;
use kortex_i18n::Catalog;
use kortex_runtime::{FileData, ToolError, ValueMap};

use crate::{Mode, Runner, SaveFile, visible_params};

/// Outcome of the last run: `None` until a run finishes (or after a new run starts).
pub type RunResult = Option<Result<ValueMap, ToolError>>;

/// State and actions a custom tool UI receives from its host.
#[derive(Clone)]
pub struct ToolHandle {
    pub contract: ToolContract,
    /// Variant id requested by the host (SEO preset), if any.
    pub variant: Option<String>,
    lang: Signal<String>,
    locale: Signal<Catalog>,
    mode: Signal<Mode>,
    running: Signal<bool>,
    result: Signal<RunResult>,
    generation: Signal<u64>,
    runner: Runner,
    save_file: Option<SaveFile>,
    on_cancel: Option<EventHandler<()>>,
}

impl ToolHandle {
    /// Current language code (`fr` / `en`).
    #[must_use]
    pub fn lang(&self) -> String {
        (self.lang)()
    }

    /// Translation from the tool's `locales/<lang>.toml`; the key itself when missing.
    #[must_use]
    pub fn t(&self, key: &str) -> String {
        self.locale.read().t(key).to_owned()
    }

    /// Effective Simple/Medium/Pro mode (host-driven, overridable by the UI).
    #[must_use]
    pub fn mode(&self) -> Mode {
        (self.mode)()
    }

    pub fn set_mode(&mut self, mode: Mode) {
        self.mode.set(mode);
    }

    /// Params the contract exposes in the current mode.
    #[must_use]
    pub fn visible_param_ids(&self) -> Vec<String> {
        visible_params(&self.contract, self.mode())
            .into_iter()
            .map(|p| p.id.clone())
            .collect()
    }

    #[must_use]
    pub fn running(&self) -> bool {
        (self.running)()
    }

    /// Last finished run, cloned for rendering.
    #[must_use]
    pub fn result(&self) -> RunResult {
        self.result.read().clone()
    }

    /// Starts a run through the host executor (Worker on web, native runner on desktop).
    pub fn run(&mut self, inputs: ValueMap, params: ValueMap) {
        self.generation += 1;
        let started = (self.generation)();
        self.running.set(true);
        self.result.set(None);
        let (runner, generation) = (self.runner, self.generation);
        let (mut running, mut result) = (self.running, self.result);
        spawn(async move {
            let outcome = (runner.0)(inputs, params).await;
            if generation() == started {
                result.set(Some(outcome));
                running.set(false);
            }
        });
    }

    /// Cancels the current run: stale results are dropped and an isolated executor is stopped.
    pub fn cancel(&mut self) {
        self.generation += 1;
        if let Some(cancel) = self.on_cancel {
            cancel.call(());
        }
        self.running.set(false);
        self.result.set(Some(Err(ToolError::new("cancelled"))));
    }

    /// Native save on desktop (`Some(path)`); `None` means the host uses a browser download.
    #[must_use]
    pub fn save(&self, file: &FileData) -> Option<Result<String, String>> {
        self.save_file.map(|save| (save.0)(file))
    }
}

/// Access the host from a custom `Ui` component. Must be rendered inside [`ToolHost`].
pub fn use_tool() -> ToolHandle {
    use_context::<ToolHandle>()
}

/// Provides [`ToolHandle`] to `children`; props mirror [`crate::AutoTool`].
#[component]
pub fn ToolHost(
    contract: ToolContract,
    lang: String,
    locale: Catalog,
    runner: Runner,
    variant: Option<String>,
    host_mode: Option<String>,
    save_file: Option<SaveFile>,
    #[props(default)] on_cancel: Option<EventHandler<()>>,
    children: Element,
) -> Element {
    let mut mode = use_signal(|| {
        host_mode
            .as_deref()
            .and_then(Mode::from_id)
            .unwrap_or_default()
    });
    use_effect(use_reactive!(|host_mode| {
        if let Some(m) = host_mode.as_deref().and_then(Mode::from_id) {
            mode.set(m);
        }
    }));
    let mut lang_signal = use_signal(|| lang.clone());
    let mut locale_signal = use_signal(|| locale.clone());
    use_effect(use_reactive!(|lang, locale| {
        lang_signal.set(lang);
        locale_signal.set(locale);
    }));
    let running = use_signal(|| false);
    let result = use_signal(|| None);
    let generation = use_signal(|| 0_u64);
    use_context_provider(|| ToolHandle {
        contract,
        variant,
        lang: lang_signal,
        locale: locale_signal,
        mode,
        running,
        result,
        generation,
        runner,
        save_file,
        on_cancel,
    });
    rsx! { {children} }
}
